#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/gate_files.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="The file list of one code:format or code:lint gate"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# The file list of one code:format or code:lint gate. The bash function
# gate_files of helpers runs it as
#
#   gate_files.py <gate file> [--all] [--debug] [--fix] [<file>...]
#
# The base set: the given files, or with --all every file of this repository,
# or else the uncommitted files (staged, changed and new). Then three filters,
# in this order: the repository filter, the global filter of
# .config/bootstrap/config-files.toml, and the #FILES header of the gate file.
# The header line starts with "#FILES " or "# FILES " (ruff format adds the
# space).
# It writes the sorted list to a new temporary file, one path for each line,
# and prints the path of that file. The gate deletes the file.
#
# With --debug, each removed file gives one line on stderr:
#   drop <path>: <layer> <kind> ["<pattern>"]
#
# Exit 0 on success; 2 for a usage error, a malformed header or pattern, or an
# unreadable config-files.toml; the code of git when git fails.

import argparse
import os
import posixpath
import re
import stat
import subprocess
import sys
import tempfile
import tomllib

CONFIG_FILES = ".config/bootstrap/config-files.toml"
HEADER_KEYS = ("include", "exclude", "shebang")
HEADER_PREFIXES = ("#FILES ", "# FILES ")
KNOWN_SHELLS = ("sh", "bash", "dash", "ksh", "mksh", "zsh", "fish", "csh", "tcsh")


class Malformed(Exception):
  pass


class GitFailed(Exception):
  def __init__(self, code):
    super().__init__(code)
    self.code = code


def fail(message):
  print(f"gate_files: {message}", file=sys.stderr)
  sys.exit(2)


def git(root, *args):
  """The NUL-separated output of a git command in <root>, as a list."""
  done = subprocess.run(
    ["git", "-c", "core.quotePath=off", "-C", root, *args, "-z"],
    stdout=subprocess.PIPE,
  )
  if done.returncode != 0:
    raise GitFailed(done.returncode)
  return [p for p in done.stdout.decode("utf-8", "surrogateescape").split("\0") if p]


# The patterns: the gitignore glob form, without negation.


def glob_to_regex(glob):
  """The regex of a glob with no leading or trailing /."""
  out = []
  i = 0
  n = len(glob)
  while i < n:
    c = glob[i]
    if glob.startswith("**/", i) and (i == 0 or glob[i - 1] == "/"):
      out.append("(?:.*/)?")
      i += 3
    elif glob.startswith("**", i) and (i == 0 or glob[i - 1] == "/") and i + 2 == n:
      out.append(".*")
      i += 2
    elif c == "*":
      out.append("[^/]*")
      i += 1
    elif c == "?":
      out.append("[^/]")
      i += 1
    elif c == "[":
      end = glob.find("]", i + 2 if glob.startswith("[!", i) or glob.startswith("[^", i) else i + 1)
      if end < 0:
        out.append(re.escape(c))
        i += 1
        continue
      body = glob[i + 1 : end]
      if body[:1] in ("!", "^"):
        body = "^" + body[1:]
      out.append("[" + body.replace("\\", "\\\\") + "]")
      i = end + 1
    else:
      out.append(re.escape(c))
      i += 1
  return "".join(out)


def compile_pattern(pattern):
  """A compiled pattern: it matches a file path relative to the root."""
  if pattern.startswith("!"):
    raise Malformed(f'pattern "{pattern}": negation is not supported')
  body = pattern
  folder = body.endswith("/")
  body = body.rstrip("/")
  anchored = body.startswith("/") or "/" in body
  body = body.lstrip("/")
  if not body:
    raise Malformed(f'pattern "{pattern}": empty')
  # A folder pattern matches each path below the folder; any other pattern
  # matches the path itself, or each path below a folder of that name.
  tail = "/.*" if folder else "(?:/.*)?"
  head = "" if anchored else "(?:.*/)?"
  return re.compile(head + glob_to_regex(body) + tail + r"\Z", re.DOTALL)


def compile_list(patterns, where):
  try:
    return [(p, compile_pattern(p)) for p in patterns]
  except Malformed as err:
    fail(f"{where}: {err}")


def first_match(compiled, path):
  for pattern, regex in compiled:
    if regex.match(path):
      return pattern
  return None


# The lists.


def read_header(gate):
  """The #FILES lists of the gate file: include, exclude, shebang (or None).

  The header line starts with "#FILES " or "# FILES "."""
  try:
    with open(gate, encoding="utf-8", errors="surrogateescape") as f:
      lines = f.read().splitlines()
  except OSError as err:
    fail(f"cannot read the gate file {gate}: {err.strerror}")
  found = []
  for line in lines:
    if line.strip() and not line.startswith("#"):
      break
    for prefix in HEADER_PREFIXES:
      if line.startswith(prefix):
        found.append(line[len(prefix) :])
  if len(found) > 1:
    fail(f"{gate}: two #FILES lines")
  header = {}
  if not found:
    return header
  rest = found[0]
  pos = 0
  item = re.compile(r'\s*([^\s=]+)=("([^"]*)"|\S*)')
  while rest[pos:].strip():
    m = item.match(rest, pos)
    if not m:
      fail(f"{gate}: malformed #FILES line")
    key, raw, value = m.group(1), m.group(2), m.group(3)
    if key not in HEADER_KEYS:
      fail(f"{gate}: unknown #FILES key {key}")
    if key in header:
      fail(f"{gate}: the #FILES key {key} is twice")
    if value is None or not raw.startswith('"'):
      fail(f"{gate}: the #FILES value of {key} has no double quotes")
    header[key] = value.split()
    pos = m.end()
    if pos < len(rest) and not rest[pos].isspace():
      fail(f"{gate}: malformed #FILES line")
  return header


def read_config(root):
  """The global includes and excludes; a missing file gives two empty lists."""
  path = os.path.join(root, CONFIG_FILES)
  try:
    with open(path, "rb") as f:
      data = tomllib.load(f)
  except FileNotFoundError:
    return [], []
  except (OSError, tomllib.TOMLDecodeError) as err:
    fail(f"cannot read {CONFIG_FILES}: {err}")
  lists = []
  for key in ("includes", "excludes"):
    value = data.get(key, [])
    if not isinstance(value, list) or not all(isinstance(v, str) for v in value):
      fail(f"{CONFIG_FILES}: {key} is not a list of strings")
    lists.append(value)
  return lists[0], lists[1]


# The base set and the repository filter.


def normalize(root, path):
  """A given path relative to the root, or None for a path outside it."""
  if os.path.isabs(path):
    path = posixpath.normpath(path)
    for base in (root, os.path.realpath(root)):
      base = base.rstrip("/")
      if path.startswith(base + "/"):
        return path[len(base) + 1 :]
    return None
  path = posixpath.normpath(path)
  if path == "." or path == ".." or path.startswith("../"):
    return None
  return path


def interpreter(root, path):
  """The interpreter of the #! line of a file, or None."""
  try:
    with open(os.path.join(root, path), "rb") as f:
      line = f.readline(4096).decode("utf-8", "replace")
  except OSError:
    return None
  if not line.startswith("#!"):
    return None
  words = line[2:].split()
  if not words:
    return None
  name = posixpath.basename(words[0])
  if name != "env":
    return name
  for word in words[1:]:
    if not word.startswith("-"):
      return posixpath.basename(word)
  return None


def main():
  parser = argparse.ArgumentParser(prog="gate_files.py")
  parser.add_argument("gate")
  parser.add_argument("--all", action="store_true")
  parser.add_argument("--debug", action="store_true")
  parser.add_argument("--fix", action="store_true")  # accepted and ignored
  parser.add_argument("files", nargs="*")
  args = parser.parse_args()

  if args.all and args.files:
    print("gate_files: use --all or files, not both", file=sys.stderr)
    return 2
  root = os.environ.get("MISE_PROJECT_ROOT", "")
  if not root:
    fail("MISE_PROJECT_ROOT is not set")

  header = read_header(args.gate)
  gate_include = compile_list(header.get("include", []), args.gate)
  gate_exclude = compile_list(header.get("exclude", []), args.gate)
  shebang = header.get("shebang")
  includes, excludes = read_config(root)
  global_include = compile_list(includes, CONFIG_FILES)
  global_exclude = compile_list(excludes, CONFIG_FILES)

  def drop(path, layer, kind, pattern=None):
    if args.debug:
      line = f"drop {path}: {layer} {kind}"
      if pattern is not None:
        line += f' "{pattern}"'
      print(line, file=sys.stderr)

  try:
    listed = set(git(root, "ls-files", "--cached", "--others", "--exclude-standard"))
    gitlinks = set()
    for entry in git(root, "ls-files", "--stage"):
      meta, _, path = entry.partition("\t")
      if meta.startswith("160000 "):
        gitlinks.add(path)
    if args.files:
      base = []
      for given in args.files:
        path = normalize(root, given)
        if path is None:
          drop(given, "repo", "unlisted")
        else:
          base.append(path)
    elif args.all:
      base = sorted(listed)
    else:
      base = git(root, "diff", "--cached", "--name-only", "--diff-filter=d")
      base += git(root, "ls-files", "--modified")
      base += git(root, "ls-files", "--others", "--exclude-standard")
  except GitFailed as err:
    return err.code

  kept = []
  for path in sorted(set(base)):
    # The repository filter. Each gate reads the list one path for each line
    # and passes it to a tool, so a name with a line break or a leading dash
    # never reaches the list.
    if "\n" in path or "\r" in path or path.startswith("-"):
      drop(path, "repo", "unsafe-name")
      continue
    if path not in listed:
      drop(path, "repo", "unlisted")
      continue
    if path in gitlinks:
      drop(path, "repo", "gitlink")
      continue
    if path.endswith("/"):
      drop(path, "repo", "nested-repo")
      continue
    try:
      mode = os.lstat(os.path.join(root, path)).st_mode
    except OSError:
      mode = 0
    if stat.S_ISLNK(mode):
      drop(path, "repo", "symlink")
      continue
    if not stat.S_ISREG(mode):
      drop(path, "repo", "deleted")
      continue

    # The global filter.
    if global_include and first_match(global_include, path) is None:
      drop(path, "global", "include")
      continue
    pattern = first_match(global_exclude, path)
    if pattern is not None:
      drop(path, "global", "exclude", pattern)
      continue

    # The gate filter. No include list selects every file. With a shebang
    # list, a file that only the shebang selects needs an interpreter in the
    # list, and a file that the include names select is dropped when its
    # interpreter is a known shell that is not in the list.
    interp = interpreter(root, path) if shebang is not None else None
    named = not gate_include or first_match(gate_include, path) is not None
    if not named and not (shebang is not None and interp in shebang):
      drop(path, "gate", "include")
      continue
    pattern = first_match(gate_exclude, path)
    if pattern is not None:
      drop(path, "gate", "exclude", pattern)
      continue
    if named and shebang is not None and interp in KNOWN_SHELLS and interp not in shebang:
      drop(path, "gate", "shebang")
      continue
    kept.append(path)

  fd, list_file = tempfile.mkstemp(prefix="gate-files-", suffix=".txt")
  with os.fdopen(fd, "w", encoding="utf-8", errors="surrogateescape") as f:
    for path in kept:
      f.write(path + "\n")
  print(list_file)
  return 0


if __name__ == "__main__":
  sys.exit(main())
